import{_ as t,c as a,a2 as o,o as s}from"./chunks/framework.CoXjB5sU.js";const u=JSON.parse('{"title":"Browse - ioChem-BD module - REST API","description":"","frontmatter":{},"headers":[],"relativePath":"api/browse.md","filePath":"api/browse.md"}'),i={name:"api/browse.md"};function r(c,e,d,n,l,h){return s(),a("div",null,e[0]||(e[0]=[o(`<h1 id="browse-iochem-bd-module-rest-api" tabindex="-1">Browse - ioChem-BD module - REST API <a class="header-anchor" href="#browse-iochem-bd-module-rest-api" aria-label="Permalink to &quot;Browse - ioChem-BD module - REST API&quot;">​</a></h1><p>You can find out more about ioChem-BD at <a href="https://www.iochem-bd.org/" target="_blank" rel="noreferrer">https://www.iochem-bd.org/</a>.</p><p>Additional links:</p><ul><li>Project <a href="https://gitlab.com/ioChem-BD/iochem-bd" target="_blank" rel="noreferrer">source code</a></li><li>Create module <a href="./create.html">API</a></li><li>Browse module <a href="./browse.html">API</a></li><li>Find Central Service <a href="./find.html">API</a></li></ul><h2 id="base-url" tabindex="-1">Base URL <a class="header-anchor" href="#base-url" aria-label="Permalink to &quot;Base URL&quot;">​</a></h2><p>The Browse module is built on DSpace and exposes the standard <a href="https://github.com/DSpace/RestContract" target="_blank" rel="noreferrer">DSpace REST API</a> (HAL+JSON). Each ioChem-BD instance has its own URL; replace the hostname with yours:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    https://&lt;hostname&gt;/browse/server/api</span></span></code></pre></div><p>Opening <code>https://&lt;hostname&gt;/browse/server/</code> in a browser shows the <em>HAL Browser</em>, an interactive explorer of the API: follow the links of each resource to discover the available endpoints.</p><p><strong>License:</strong> <a href="https://www.gnu.org/licenses/agpl-3.0.en.html" target="_blank" rel="noreferrer">AGPL 3.0</a> · <strong>Contact:</strong> <a href="mailto:contact@iochem-bd.org" target="_blank" rel="noreferrer">contact@iochem-bd.org</a></p><h2 id="public-read-access" tabindex="-1">Public read access <a class="header-anchor" href="#public-read-access" aria-label="Permalink to &quot;Public read access&quot;">​</a></h2><p>Published content (not under embargo) can be read without authentication. These are the most useful endpoints:</p><table tabindex="0"><thead><tr><th>Endpoint</th><th>Description</th></tr></thead><tbody><tr><td><code>GET /core/communities/search/top</code></td><td>Top-level communities (usually one per research group)</td></tr><tr><td><code>GET /core/communities/{uuid}/collections</code></td><td>Collections (published projects) of a community</td></tr><tr><td><code>GET /core/collections/{uuid}</code></td><td>A collection and its metadata</td></tr><tr><td><code>GET /core/items/{uuid}</code></td><td>An item (published calculation, report or asset) and its metadata</td></tr><tr><td><code>GET /core/items/{uuid}/bundles</code></td><td>The files of an item, grouped in bundles (<code>ORIGINAL</code> holds the uploaded files)</td></tr><tr><td><code>GET /core/bitstreams/{uuid}/content</code></td><td>Downloads a file</td></tr><tr><td><code>GET /discover/search/objects?query=...&amp;dsoType=ITEM</code></td><td>Full-text search, with the same filters as the Browse search page</td></tr><tr><td><code>GET /pid/find?id={handle}</code></td><td>Resolves a handle (e.g. <code>100/72</code>) to its object</td></tr></tbody></table><p>Lists are paginated: use the <code>page</code> and <code>size</code> parameters and follow the <code>next</code> link of the response.</p><h3 id="example-search-and-read-a-calculation" tabindex="-1">Example: search and read a calculation <a class="header-anchor" href="#example-search-and-read-a-calculation" aria-label="Permalink to &quot;Example: search and read a calculation&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Find calculations matching &quot;water&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;https://&lt;hostname&gt;/browse/server/api/discover/search/objects?query=water&amp;dsoType=ITEM&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Read one of the returned items</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;https://&lt;hostname&gt;/browse/server/api/core/items/56ee6579-c28e-4e9e-a8f9-a66a3d6788d6&#39;</span></span></code></pre></div><p>Besides the Dublin Core fields (<code>dc.title</code>, <code>dc.contributor.author</code>, ...), the metadata of a calculation holds the chemistry fields extracted from its CML file, in the <code>cml</code> schema: for example <code>cml.formula.generic</code>, <code>cml.method</code>, <code>cml.basisset</code>, <code>cml.calculationtype</code>, <code>cml.charge</code>, <code>cml.multiplicity</code> and <code>cml.energy.value</code>.</p><h2 id="authenticated-access" tabindex="-1">Authenticated access <a class="header-anchor" href="#authenticated-access" aria-label="Permalink to &quot;Authenticated access&quot;">​</a></h2><p>Embargoed content and administrative operations need an authenticated session. Authentication goes through the ioChem-BD login page (CAS, with OpenID Connect): <code>GET /authn/status</code> reports it in its <code>WWW-Authenticate</code> header, together with the login location. The Browse web interface handles this login for its users; API clients act on behalf of a logged-in session and must send the CSRF token in every <code>POST</code>, <code>PUT</code>, <code>PATCH</code> and <code>DELETE</code> request (<code>DSPACE-XSRF-TOKEN</code> response header, sent back in the <code>X-XSRF-TOKEN</code> request header). See the <a href="https://github.com/DSpace/RestContract/blob/main/authentication.md" target="_blank" rel="noreferrer">DSpace REST authentication</a> documentation for the details.</p><p>Reviewers of an embargoed collection don&#39;t need an account: the peer review link of the collection gives them access (see <a href="/doc/guides/usage/publishing-calculations/embargo.html">Setting the embargo</a>).</p>`,19)]))}const m=t(i,[["render",r]]);export{u as __pageData,m as default};
